							<td id="article_byline">
								by <b>Richard Fisher</b> on <b>April 29, 2008</b>
							</td><td id="article_category">
								Categories: <b><a href="/category.php?id=322&category=Switchers & Amplifiers">Switchers & Amplifiers</a></b>
